from abc import ABC, abstractmethod

# Abstracciones (interfaces)
class Database(ABC):
    '''Abstracción: cualquier base de datos debe implementar esto'''

    @abstractmethod
    def connect(self):
        pass

    @abstractmethod
    def query(self, sql):
        pass

    @abstractmethod
    def disconnect(self):
        pass


class EmailClient(ABC):
    '''Abstracción: cualquier cliente de email debe implementar esto'''

    @abstractmethod
    def send(self, to, subject, body):
        pass


# Implementaciones concretas
class MySQLDatabase(Database):
    '''Implementación concreta: MySQL'''

    def connect(self):
        return 'Connected to MySQL'

    def query(self, sql):
        return f'MySQL result: {sql}'

    def disconnect(self):
        return 'Disconnected from MySQL'


class PostgreSQLDatabase(Database):
    '''Implementación concreta: PostgreSQL'''

    def connect(self):
        return 'Connected to PostgreSQL'

    def query(self, sql):
        return f'PostgreSQL result: {sql}'

    def disconnect(self):
        return 'Disconnected from PostgreSQL'


class SmtpEmailClient(EmailClient):
    '''Implementación concreta: SMTP'''

    def send(self, to, subject, body):
        return f'SMTP email to {to}'


class SendGridEmailClient(EmailClient):
    '''Implementación concreta: SendGrid'''

    def send(self, to, subject, body):
        return f'SendGrid email to {to}'


# Módulo de alto nivel: DEPENDE DE ABSTRACCIONES
class OrderService:
    '''Cumple DIP: depende de Database y EmailClient (abstracciones)'''

    def __init__(self, db: Database, email: EmailClient):
        # Inyección de dependencias: recibe abstracciones
        self.db = db
        self.email = email

    def process_order(self, order_data):
        # Usa la abstracción, no sabe si es MySQL o PostgreSQL
        self.db.connect()
        result = self.db.query('INSERT INTO orders ...')

        # Usa la abstracción, no sabe si es SMTP o SendGrid
        self.email.send(
            to=order_data['email'],
            subject='Order Confirmation',
            body='Your order has been processed'
        )

        self.db.disconnect()
        return result


# Uso: inyectar dependencias concretas
mysql_db = MySQLDatabase()
smtp_email = SmtpEmailClient()
service = OrderService(db=mysql_db, email=smtp_email)
service.process_order({'email': 'user@example.com'})

# Cambiar implementaciones SIN MODIFICAR OrderService:
postgres_db = PostgreSQLDatabase()
sendgrid_email = SendGridEmailClient()
service2 = OrderService(db=postgres_db, email=sendgrid_email)
service2.process_order({'email': 'user@example.com'})

# LSP cumplido: OrderService funciona con cualquier Database y EmailClient
# DIP cumplido: OrderService depende de abstracciones, no de concreciones

