class Database(ABC):
    '''Abstracción: cualquier base de datos'''

    @abstractmethod
    def connect(self):
        pass

    @abstractmethod
    def query(self, sql):
        pass


class MySQLDatabaseFixed(Database):
    def connect(self):
        return 'Connected to MySQL'

    def query(self, sql):
        return f'MySQL result: {sql}'


class PostgreSQLDatabase(Database):
    def connect(self):
        return 'Connected to PostgreSQL'

    def query(self, sql):
        return f'PostgreSQL result: {sql}'


class SQLiteDatabaseFixed(Database):
    def __init__(self, db_path=':memory:'):
        self.db_path = db_path
        self._conn = None

    def connect(self):
        self._conn = sqlite3.connect(self.db_path)
        return f'Connected to SQLite at {self.db_path}'

    def query(self, sql):
        if self._conn is None:
            self.connect()
        cursor = self._conn.execute(sql)
        return cursor.fetchall()


class OrderServiceWithDIP:
    '''Cumple DIP: depende de Database (abstracción)'''

    def __init__(self, db: Database):
        # Inyección de dependencias: recibe abstracción
        self.db = db

    def get_orders(self):
        self.db.connect()
        return self.db.query('SELECT * FROM orders')


print('--- Con DIP ---')

# Usar MySQL
mysql_db = MySQLDatabaseFixed()
service_mysql = OrderServiceWithDIP(db=mysql_db)
print(f'Con MySQL: {service_mysql.get_orders()}')

# Cambiar a PostgreSQL SIN MODIFICAR OrderServiceWithDIP
postgres_db = PostgreSQLDatabase()
service_postgres = OrderServiceWithDIP(db=postgres_db)
print(f'Con PostgreSQL: {service_postgres.get_orders()}')

# Cambiar a SQLite SIN MODIFICAR OrderServiceWithDIP
sqlite_db = SQLiteDatabaseFixed()
service_sqlite = OrderServiceWithDIP(db=sqlite_db)
print(f'Con SQLite: {service_sqlite.get_orders()}')

print()
print('✓ DIP cumplido: OrderServiceWithDIP funciona con cualquier Database')
print('✓ Cambiar implementación NO requiere modificar OrderServiceWithDIP')

