# 1. Constructor Injection (recomendado)
class ServiceWithConstructor:
    def __init__(self, db: Database):
        self.db = db

    def work(self):
        return self.db.query('SELECT 1')

# 2. Setter Injection
class ServiceWithSetter:
    def __init__(self):
        self._db = None

    def set_db(self, db: Database):
        self._db = db

    def work(self):
        if self._db is None:
            raise RuntimeError('Database not set')
        return self._db.query('SELECT 1')

# Uso de Constructor Injection
service1 = ServiceWithConstructor(db=MySQLDatabaseFixed())
print(f'Constructor Injection: {service1.work()}')

# Uso de Setter Injection
service2 = ServiceWithSetter()
service2.set_db(PostgreSQLDatabase())
print(f'Setter Injection: {service2.work()}')

print()
print('Constructor Injection es más común y claro:')
print('  - Dependencias explícitas desde la creación')
print('  - Objeto siempre en estado válido')
print('  - Más fácil de testear con mocks')

@runtime_checkable
class Notifier(Protocol):
    def notify(self, message: str) -> None:
        ...


class EmailNotifier:
    def notify(self, message: str) -> None:
        print(f'Email: {message}')


class SMSNotifier:
    def notify(self, message: str) -> None:
        print(f'SMS: {message}')


class SlackNotifier:
    def notify(self, message: str) -> None:
        print(f'Slack: {message}')


class NotificationService:
    '''Depende de Notifier (Protocol)'''

    def __init__(self, notifier: Notifier):
        self.notifier = notifier

    def send_alert(self, message: str):
        self.notifier.notify(message)


print('--- DIP con Protocols ---')

# Notifier puede ser EmailNotifier, SMSNotifier, o SlackNotifier
email_notifier = EmailNotifier()
sms_notifier = SMSNotifier()
slack_notifier = SlackNotifier()

service_email = NotificationService(notifier=email_notifier)
service_sms = NotificationService(notifier=sms_notifier)
service_slack = NotificationService(notifier=slack_notifier)

print('Email:')
service_email.send_alert('Order confirmed')

print('SMS:')
service_sms.send_alert('Order confirmed')

print('Slack:')
service_slack.send_alert('Order confirmed')

print()
print('✓ NotificationService funciona con cualquier Notifier')
print('✓ Protocol permite duck typing con verificación estática')
print('✓ No necesitas heredar, solo implementar notify()')

class ServiceFactory:
    '''Factory para crear servicios con sus dependencias'''

    def __init__(self, config: dict):
        self.config = config

    def create_database(self) -> Database:
        db_type = self.config.get('db_type', 'sqlite')

        if db_type == 'mysql':
            return MySQLDatabaseFixed()
        elif db_type == 'postgresql':
            return PostgreSQLDatabase()
        elif db_type == 'sqlite':
            return SQLiteDatabaseFixed()
        else:
            raise ValueError(f'Unknown db_type: {db_type}')

    def create_order_service(self) -> OrderServiceWithDIP:
        db = self.create_database()
        return OrderServiceWithDIP(db=db)


print('--- Factory Pattern ---')

# Configuración 1: MySQL
config_mysql = {'db_type': 'mysql'}
factory_mysql = ServiceFactory(config_mysql)
service_mysql = factory_mysql.create_order_service()
print(f'Factory (MySQL): {service_mysql.get_orders()}')

# Configuración 2: SQLite
config_sqlite = {'db_type': 'sqlite'}
factory_sqlite = ServiceFactory(config_sqlite)
service_sqlite = factory_sqlite.create_order_service()
print(f'Factory (SQLite): {service_sqlite.get_orders()}')

print()
print('✓ Factory encapsula la creación de dependencias')
print('✓ Cambiar configuración NO requiere modificar OrderServiceWithDIP')
